CREATE OR REPLACE FUNCTION get_integration_index(p_equip_code text)
RETURNS numeric AS $$
DECLARE
    v_esi numeric;
    v_wrmi numeric;
    v_heater_temp numeric;
    v_ewrii numeric;
BEGIN
    SELECT INTO v_esi, v_heater_temp
        COALESCE((pb.battery_telemetry->'power_state'->>'conversion_eff_pct')::real * 
        CASE 
            WHEN COALESCE(pb.battery_telemetry->'power_state'->>'primary_source', '') IN ('Solar', 'Wind', 'Hybrid') THEN 1.5
            WHEN COALESCE(pb.battery_telemetry->'power_state'->>'primary_source', '') = 'Battery' THEN 1.0
            WHEN COALESCE(pb.battery_telemetry->'power_state'->>'primary_source', '') = 'Diesel' THEN 0.7
            ELSE 0
        END, 0),
        COALESCE((ce.cabin_env_snapshot->'hvac'->>'heater_temp_c')::real, 0)
    FROM "PowerBattery" pb
    LEFT JOIN "CabinEnvironment" ce ON pb.equip_ref = ce."equipRef"
    WHERE pb.equip_ref = p_equip_code;

    SELECT INTO v_wrmi
        COALESCE("waterLevelPct", 0) / 100.0 * 
        COALESCE("waterQualityIdx", 0) / 100.0 * 
        (1 - COALESCE("wasteTankPct", 0) / 100.0)
    FROM "WaterAndWaste"
    WHERE "equipRef" = p_equip_code;

    v_ewrii := 0.5 * v_esi + 0.5 * v_wrmi * (1 - v_heater_temp / 100.0);

    RETURN ROUND(CAST(v_ewrii AS numeric), 4);
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION get_integration_index(p_equip_code text)
RETURNS TABLE (equip_code text, ewrii numeric) AS $$
DECLARE
    v_conv_eff real;
    v_source text;
    v_water_pct real;
    v_quality_idx bigint;
    v_waste_pct real;
    v_heater_temp real;
BEGIN
    SELECT (battery_telemetry->'power_state'->>'conversion_eff_pct')::real, battery_telemetry->'power_state'->>'primary_source'
    INTO v_conv_eff, v_source FROM "PowerBattery" WHERE equip_ref = p_equip_code;

    SELECT "waterLevelPct", "waterQualityIdx", "wasteTankPct"
    INTO v_water_pct, v_quality_idx, v_waste_pct FROM "WaterAndWaste" WHERE "equipRef" = p_equip_code;

    SELECT (cabin_env_snapshot->'hvac'->>'heater_temp_c')::real
    INTO v_heater_temp FROM "CabinEnvironment" WHERE "equipRef" = p_equip_code;

    RETURN QUERY
    SELECT p_equip_code::text,
        ROUND(CAST(
            0.5 * COALESCE(v_conv_eff, 0) * 
            CASE 
                WHEN v_source IN ('Solar', 'Wind', 'Hybrid') THEN 1.5
                WHEN v_source = 'Battery' THEN 1.0
                WHEN v_source = 'Diesel' THEN 0.7
                ELSE 0
            END + 
            0.5 * COALESCE(v_water_pct, 0) / 100.0 * COALESCE(v_quality_idx, 0) / 100.0 * (1 - COALESCE(v_waste_pct, 0) / 100.0) * 
            (1 - COALESCE(v_heater_temp, 0) / 100.0)
        AS numeric), 4);
END;
$$ LANGUAGE plpgsql;

